#nullable enable // autogenerated

using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;

namespace MVZ2Logic.Buffs
{
    public static class LogicBuffExt
    {
        #region 获取或初始化计时器
        public static FrameTimer GetOrCreateTimer(this Buff buff, PropertyKey<FrameTimer> key, int frames)
        {
            var timer = buff.GetProperty(key);
            if (timer == null)
            {
                timer = new FrameTimer(frames);
                buff.SetProperty(key, timer);
            }
            return timer;
        }
        public static FrameTimer GetOrCreateTimerSeconds(this Buff buff, PropertyKey<FrameTimer> key, float seconds)
        {
            var timer = buff.GetProperty(key);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(seconds);
                buff.SetProperty(key, timer);
            }
            return timer;
        }
        #endregion
    }
}